public class Main {
    static void add(StringBuilder sb, long v) {
        if (sb.length() > 0) {
            sb.append(' ');
        }
        sb.append(v);
    }

    static void siftDown(int[] a, int n, int i) {
        while (true) {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int largest = i;
            if (left < n && a[left] > a[largest]) {
                largest = left;
            }
            if (right < n && a[right] > a[largest]) {
                largest = right;
            }
            if (largest == i) {
                return;
            }
            int tmp = a[i];
            a[i] = a[largest];
            a[largest] = tmp;
            i = largest;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        for (int i = n / 2 - 1; i >= 0; i--) {
            siftDown(a, n, i);
        }
        StringBuilder sb = new StringBuilder();
        for (int v : a) {
            add(sb, v);
        }
        System.out.println(sb);
    }
