        }
        if (n == 0 || a[0] == -1) {
            return null;
        }
        Node root = new Node(a[0]);
        ArrayDeque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < n) {
            Node cur = queue.poll();
            if (i < n && a[i] != -1) {
                cur.left = new Node(a[i]);
                queue.add(cur.left);
            }
            i++;
            if (i < n && a[i] != -1) {
                cur.right = new Node(a[i]);
                queue.add(cur.right);
            }
            i++;
        }
        return root;
    }

    static long best;

    // Returns {isBst (1/0), min, max, sum}; an empty subtree is a BST with min = +inf and max = -inf.
    static long[] solve(Node node) {
        if (node == null) {
            return new long[] {1, Long.MAX_VALUE, Long.MIN_VALUE, 0};
        }
        long[] left = solve(node.left);
        long[] right = solve(node.right);
        if (left[0] == 1 && right[0] == 1 && left[2] < node.val && node.val < right[1]) {
            long sum = left[3] + right[3] + node.val;
            best = Math.max(best, sum);
            return new long[] {1, Math.min(left[1], node.val), Math.max(right[2], node.val), sum};
        }
        return new long[] {0, 0, 0, 0};
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        Node root = buildTree(sc, n);
        best = 0;
        solve(root);
        System.out.println(best);
    }
